python3 -I -c "import json,hashlib; from pathlib import Path; from collections import Counter; errors=[]; stats=Counter(); dims={'correctness':'answer_correctness','grounding':'source_grounding','fidelity':'reading_fidelity'}; outcomes=['correct','partial','incorrect','missing','unsupported','unverified','error']; fixtures=sorted(Path('benchmark/challenges').glob('*.json'))
def resolve(obj,p):
 for token in p.split('/')[1:]:
  token=token.replace('~1','/').replace('~0','~'); obj=obj[int(token)] if isinstance(obj,list) else obj[token]
 return obj
def walk(obj,where):
 if isinstance(obj,dict):
  if 'inventory' in obj and 'json_pointer' in obj:
   stats['inventory_pointers']+=1
   try: resolve(json.loads(Path(obj['inventory']).read_text()),obj['json_pointer'])
   except Exception as e: errors.append([where,'inventory pointer',str(e)])
  for k,v in obj.items(): walk(v,where+'/'+k)
 elif isinstance(obj,list):
  for i,v in enumerate(obj): walk(v,where+'/'+str(i))
def aggregate(labels,extras):
 all_labels=labels+extras
 if not labels:return 'unverified'
 if 'incorrect' in all_labels:return 'incorrect'
 if 'unverified' in all_labels:return 'unverified'
 if all(x=='correct' for x in all_labels):return 'correct'
 if any(x in ['correct','partial'] for x in all_labels):return 'partial'
 if 'error' in all_labels:return 'error'
 if all(x=='unsupported' for x in labels):return 'unsupported'
 return 'missing'
for p in fixtures:
 f=json.loads(p.read_text()); case_path=Path(f['source']['inventory_path']); case=json.loads(case_path.read_text()); assert hashlib.sha256(case_path.read_bytes()).hexdigest()==f['source']['inventory_sha256']; walk(f,p.name); print(p.name,'controls',len(f['controls']))
 for c in f['controls']:
  stats['controls']+=1; loc=p.name+':'+c['name']; e=c['expected']; s=c['submitted']
  for d,key in dims.items():
   ids=case['denominators'][key]['required_ids']; rows=e['per_id'][d]; stats['ledger_slots']+=len(rows)
   if e['required_ids'][d]!=ids or set(rows)!=set(ids) or e['fixed_denominators'][d]!=len(ids):errors.append([loc,d,'ID/denominator mismatch'])
   if e['counts'][d]!={o:list(rows.values()).count(o) for o in outcomes}:errors.append([loc,d,'count mismatch'])
   extra=[x['outcomes'][d] for x in e['extras_ledger'] if d in x['outcomes']]
   if e['dimensions'][d]!=aggregate(list(rows.values()),extra):errors.append([loc,d,'aggregate mismatch'])
  for name in ['answer_record','reader_response']:
   raw=s['raw_'+name]; stats['raw_hashes']+=1
   if hashlib.sha256(raw['text'].encode()).hexdigest()!=raw['sha256']:errors.append([loc,name,'raw hash'])
  if c['name']=='positive-control':
   for key,rows_key,id_key,den in [('answer_record','claims','claim_id','answer_correctness'),('reader_response','observations','observation_id','reading_fidelity')]:
    if [r[id_key] for r in s[key][rows_key]]!=case['denominators'][den]['required_ids']:errors.append([loc,key,'incomplete positive'])
  for r in s['answer_record']['claims']:
   if r['claim_id'].startswith('N') and (r['answer'] is not None or r['citations']):errors.append([loc,r['claim_id'],'fabricated native answer'])
  for a in c['alignment']:
   for ptr in a['raw_json_pointers']:
    try:resolve(json.loads(s['raw_reader_response']['text']),ptr);stats['raw_alignment_pointers']+=1
    except Exception as ex:errors.append([loc,ptr,str(ex)])
  for ledger in ['extras_ledger','duplicates_ledger','contradictions_ledger']:
   for row in e[ledger]:
    channel=s['answer_record' if row['channel']=='answer' else 'reader_response']; pointers=row.get('raw_json_pointers',[row.get('raw_json_pointer')])
    for ptr in pointers:
     try:resolve(channel,ptr);stats['ledger_pointers']+=1
     except Exception as ex:errors.append([loc,ptr,str(ex)])
print('SUMMARY',json.dumps(dict(stats),sort_keys=True));print('ERRORS',json.dumps(errors));print('STATUS');print(Path('benchmark/preparation-status.json').read_text());print('HISTORY MANIFEST');print(Path('.session/history/manifest.json').read_text()[:12000])"

