 case=json.loads(Path('benchmark/cases/dev/'+name+'.json').read_text()); artifact=case['artifact']; path=root/artifact['repository']/artifact['path']; data=path.read_bytes(); print(name,'original_sha256_matches',hashlib.sha256(data).hexdigest()==artifact['sha256']); tree=ET.fromstring(data)
